document.getElementById('stage').insertAdjacentHTML('beforeend',"<section class=\"screen dark active\" data-screen=\"01\" id=\"s01\">\n<div class=\"page-index\">01 / VALIDATION</div>\n<div class=\"cover-grid\">\n<div class=\"cover-copy\">\n<div class=\"kicker\"><span>OPC · ONLINE PLATFORM</span></div>\n<h1>数智健康 OPC 国际人才社区<span>在线平台建设方案</span></h1>\n<div class=\"lead\">打造“人才培养—产业需求—项目交付—OPC孵化”一体化数字运营平台</div>\n<div class=\"cover-keywords\"><span>人才</span><span>AI</span><span>中医药</span><span>产业</span></div>\n</div>\n<div class=\"cover-visual\">\n<div class=\"hero-orbit\">\n<svg aria-label=\"人才、AI、中医药与产业连接示意\" role=\"img\" viewbox=\"0 0 760 760\">\n<defs><lineargradient id=\"g1\" x1=\"0\" x2=\"1\" y1=\"0\" y2=\"1\"><stop stop-color=\"#62B99C\"></stop><stop offset=\"1\" stop-color=\"#51B9DB\"></stop></lineargradient><radialgradient id=\"halo\"><stop stop-color=\"#62B99C\" stop-opacity=\".35\"></stop><stop offset=\"1\" stop-color=\"#62B99C\" stop-opacity=\"0\"></stop></radialgradient></defs>\n<circle cx=\"385\" cy=\"376\" fill=\"url(#halo)\" r=\"264\"></circle>\n<g class=\"flowdash\" fill=\"none\" stroke=\"#78c9ae\" stroke-opacity=\".28\" stroke-width=\"1.8\">\n<path d=\"M150 156 C250 235 265 260 363 322\"></path><path d=\"M613 178 C520 238 492 275 422 330\"></path><path d=\"M116 565 C225 515 286 478 355 420\"></path><path d=\"M650 548 C548 502 500 470 430 416\"></path>\n</g>\n<g class=\"pulse\"><circle cx=\"150\" cy=\"156\" fill=\"#62B99C\" r=\"8\"></circle><circle cx=\"613\" cy=\"178\" fill=\"#51B9DB\" r=\"8\"></circle><circle cx=\"116\" cy=\"565\" fill=\"#C8A46A\" r=\"8\"></circle><circle cx=\"650\" cy=\"548\" fill=\"#62B99C\" r=\"8\"></circle></g>\n<g transform=\"translate(288 250)\">\n<circle cx=\"94\" cy=\"77\" fill=\"#183f33\" r=\"58\" stroke=\"url(#g1)\" stroke-width=\"3\"></circle>\n<circle cx=\"94\" cy=\"62\" fill=\"#b9d7ca\" r=\"30\"></circle>\n<path d=\"M34 185 C40 118 149 118 155 185 L155 232 L34 232 Z\" fill=\"#8ebfac\"></path>\n<path d=\"M50 181 C70 160 117 160 139 181\" fill=\"none\" stroke=\"#d9eee6\" stroke-opacity=\".7\" stroke-width=\"3\"></path>\n<circle cx=\"94\" cy=\"120\" fill=\"none\" r=\"94\" stroke=\"#6cc1a5\" stroke-opacity=\".20\" stroke-width=\"18\"></circle>\n<circle cx=\"94\" cy=\"120\" fill=\"none\" r=\"127\" stroke=\"#56b9d6\" stroke-dasharray=\"6 8\" stroke-opacity=\".10\" stroke-width=\"1\"></circle>\n</g>\n<g fill=\"#c6e6da\" fill-opacity=\".55\"><circle cx=\"315\" cy=\"199\" r=\"4\"></circle><circle cx=\"489\" cy=\"235\" r=\"5\"></circle><circle cx=\"291\" cy=\"495\" r=\"4\"></circle><circle cx=\"514\" cy=\"459\" r=\"5\"></circle><circle cx=\"222\" cy=\"354\" r=\"3\"></circle><circle cx=\"573\" cy=\"369\" r=\"3\"></circle></g>\n</svg>\n</div>\n<div class=\"hero-label hl1\">中医药产业场景</div><div class=\"hero-label hl2\">AI能力与知识网络</div><div class=\"hero-label hl3\">复合型人才成长</div><div class=\"hero-label hl4\">真实项目交付</div>\n</div>\n</div>\n<svg aria-hidden=\"true\" class=\"botanical\" viewbox=\"0 0 600 520\"><path d=\"M50 505 C168 408 191 310 228 116\"></path><path d=\"M194 322 C136 301 102 265 86 211\"></path><path d=\"M213 251 C279 236 316 202 337 146\"></path><path d=\"M169 386 C116 377 82 345 57 306\"></path><path d=\"M225 194 C177 170 158 143 151 105\"></path><ellipse class=\"leaf\" cx=\"100\" cy=\"228\" rx=\"42\" ry=\"17\" transform=\"rotate(41 100 228)\"></ellipse><ellipse class=\"leaf\" cx=\"308\" cy=\"184\" rx=\"47\" ry=\"18\" transform=\"rotate(-32 308 184)\"></ellipse><ellipse class=\"leaf\" cx=\"82\" cy=\"331\" rx=\"43\" ry=\"17\" transform=\"rotate(35 82 331)\"></ellipse><ellipse class=\"leaf\" cx=\"166\" cy=\"133\" rx=\"37\" ry=\"14\" transform=\"rotate(35 166 133)\"></ellipse></svg>\n<div class=\"brandmark\">数智健康 OPC 国际人才社区 · Web Presentation V0.4</div>\n</section>\n<section class=\"screen paper\" id=\"s02\" data-screen=\"02\">\n  <div class=\"page-index\">02 / FROM LAUNCH TO OPERATION</div>\n  <div class=\"eyebrow\">Community Stage</div>\n  <h1>社区已经完成“从0到1”，下一阶段进入实质运营</h1>\n  <div class=\"stage-story-grid\">\n    <div class=\"launch-panel\">\n      <div class=\"launch-date\">2026.09.05</div>\n      <h2>数智健康 OPC 国际人才社区正式揭牌</h2>\n      <p>社区聚焦中医药大健康领域，探索 AI 赋能“一人公司”人才培养新模式。</p>\n      <figure class=\"reveal-photo\"><img src=\"assets/opc-reveal.jpg\" alt=\"数智健康OPC国际人才社区揭牌现场\"/><figcaption>数智健康OPC国际人才社区揭牌现场</figcaption></figure>\n      <div class=\"transition-note\"><span>线下空间</span><i>+</i><span>线上平台</span><b>=</b><strong>完整社区运营</strong></div>\n    </div>\n    <div class=\"roadmap-rail\">\n      <div class=\"roadmap-node active\" data-road=\"6\"><div class=\"road-no\">6</div><div class=\"road-copy\"><small>MONTHS</small><h3>搭平台 · 建体系 · 育人才 · 落项目</h3><p>完成平台基础建设、课程与师资体系建设，启动首期人才培养和真实产业项目。</p></div><div class=\"road-visual rv1\"><span>平台</span><span>课程</span><span>人才</span><span>项目</span></div></div>\n      <div class=\"roadmap-node\" data-road=\"12\"><div class=\"road-no\">12</div><div class=\"road-copy\"><small>MONTHS</small><h3>形成优质项目储备</h3><p>推动优质项目进入园区中医药联合转化基金储备机制。</p></div><div class=\"road-visual rv2\"><span>案例</span><span>路演</span><span>储备</span></div></div>\n      <div class=\"roadmap-node\" data-road=\"36\"><div class=\"road-no\">36</div><div class=\"road-copy\"><small>MONTHS</small><h3>形成可复制模式</h3><p>形成“中医药 + AI OPC”数智发展模式并具备推广能力。</p></div><div class=\"road-visual rv3\"><span>标准</span><span>复制</span><span>输出</span></div></div>\n      <div class=\"road-line\"></div>\n    </div>\n  </div>\n</section>\n<section class=\"screen mist\" id=\"s03\" data-screen=\"03\">\n  <div class=\"page-index\">03 / FIVE CORE QUESTIONS</div>\n  <div class=\"eyebrow\">Why A Unified Platform</div>\n  <h1>从“建社区”到“运营社区”，需要解决五个核心问题</h1>\n  <div class=\"problem-map\">\n    <div class=\"platform-core\"><div class=\"core-rings\"></div><small>ONLINE OPERATING SYSTEM</small><strong>一套统一的线上平台</strong><p>承载人才、课程、需求、项目和孵化全过程</p></div>\n    <article class=\"problem p1\" data-problem=\"人才\"><div class=\"p-ico person-ico\">人</div><h3>人才如何持续进入社区？</h3><p>如何建档、评价、成长并形成可用的人才库？</p><span>人才资产</span></article>\n    <article class=\"problem p2\" data-problem=\"培训\"><div class=\"p-ico book-ico\">训</div><h3>学习如何转化为真实能力？</h3><p>课程、实训与真实产业项目如何连接？</p><span>训战一体</span></article>\n    <article class=\"problem p3\" data-problem=\"企业\"><div class=\"p-ico building-ico\">企</div><h3>真实项目从哪里来？</h3><p>企业数字化诉求如何进入社区并形成标准项目？</p><span>需求供给</span></article>\n    <article class=\"problem p4\" data-problem=\"项目\"><div class=\"p-ico flow-ico\">项</div><h3>项目如何真正交付？</h3><p>如何揭榜、撮合、执行、验收和沉淀？</p><span>项目闭环</span></article>\n    <article class=\"problem p5\" data-problem=\"孵化\"><div class=\"p-ico seed-ico\">孵</div><h3>项目完成以后怎么办？</h3><p>优秀人才和成果如何进一步形成 OPC 和创业项目？</p><span>持续成长</span></article>\n    <svg class=\"problem-lines\" viewBox=\"0 0 1744 720\" preserveAspectRatio=\"none\" aria-hidden=\"true\"><g><path d=\"M405 195 C600 250 700 302 824 358\"/><path d=\"M1323 190 C1150 238 1052 300 926 356\"/><path d=\"M275 520 C515 494 666 454 823 403\"/><path d=\"M1456 520 C1232 500 1080 458 925 405\"/><path d=\"M880 632 C877 558 875 493 875 437\"/></g></svg>\n  </div>\n</section>\n<section class=\"screen warm\" id=\"s04\" data-screen=\"04\">\n  <div class=\"page-index\">04 / FOUR BUILDING GOALS</div>\n  <div class=\"eyebrow\">What We Build</div>\n  <h1>平台建设的四个核心目标</h1>\n  <div class=\"goal-matrix\">\n    <article class=\"goal g1\"><div class=\"goal-top\"><span>01</span><svg viewBox=\"0 0 80 80\"><circle cx=\"40\" cy=\"28\" r=\"12\"/><path d=\"M18 67c4-20 40-20 44 0\"/><circle cx=\"57\" cy=\"22\" r=\"4\"/><path d=\"M57 26v13M50 33h14\"/></svg></div><h2>人才数字化</h2><h3>建立社区统一人才库</h3><p>实现人才注册、认证、技能标签、学习记录、项目履历、人才评价和 OPC 等级全过程沉淀。</p><div class=\"goal-value\">从“人员名单”升级为“人才数字资产”</div></article>\n    <article class=\"goal g2\"><div class=\"goal-top\"><span>02</span><svg viewBox=\"0 0 80 80\"><path d=\"M15 18h22v44H15zM43 18h22v44H43z\"/><path d=\"M26 28v24M54 28v24\"/><circle cx=\"40\" cy=\"65\" r=\"7\"/></svg></div><h2>培训实战化</h2><h3>建立训战一体培养体系</h3><p>把课程、作业、模拟实训、导师辅导与企业真实项目连接起来。</p><div class=\"goal-value\">学习结果最终由真实交付验证</div></article>\n    <article class=\"goal g3\"><div class=\"goal-top\"><span>03</span><svg viewBox=\"0 0 80 80\"><rect x=\"13\" y=\"15\" width=\"22\" height=\"19\" rx=\"4\"/><rect x=\"45\" y=\"46\" width=\"22\" height=\"19\" rx=\"4\"/><path d=\"M35 24h12c11 0 15 7 15 14M45 56H33c-11 0-15-7-15-14\"/></svg></div><h2>项目在线化</h2><h3>建立产业需求与项目交付闭环</h3><p>企业需求 → 揭榜匹配 → 项目协同 → 成果交付 → 企业验收。</p><div class=\"goal-value\">让项目全过程可协同、可追踪、可沉淀</div></article>\n    <article class=\"goal g4\"><div class=\"goal-top\"><span>04</span><svg viewBox=\"0 0 80 80\"><path d=\"M40 66V33\"/><path d=\"M40 42c-15-1-20-11-22-22 13 0 21 5 22 16M40 33c13-1 20-9 22-20-12 0-20 5-22 14\"/><path d=\"M23 66h34\"/></svg></div><h2>孵化体系化</h2><h3>建立 OPC 持续成长数字底座</h3><p>支持成果展示、创业服务、资源对接、项目路演和优质项目储备。</p><div class=\"goal-value\">让优秀成果继续成长为新的 OPC</div></article>\n  </div>\n</section>\n<section class=\"screen dark role-view\" id=\"s05\" data-screen=\"05\">\n  <div class=\"page-index\">05 / PLATFORM POSITIONING</div>\n  <div class=\"eyebrow\">Platform Positioning</div>\n  <h1>它不是一个“社区官网”，而是一套社区业务运营平台</h1>\n  <div class=\"role-hub-layout\">\n    <div class=\"role-hub\">\n      <svg class=\"hub-lines\" viewBox=\"0 0 900 710\"><path d=\"M445 352L212 166\"/><path d=\"M455 352L686 166\"/><path d=\"M445 365L202 554\"/><path d=\"M458 365L698 554\"/></svg>\n      <div class=\"hub-core\"><small>OPC OPERATING PLATFORM</small><strong>数智健康 OPC</strong><b>人才与产业协同平台</b><div class=\"hub-path\" id=\"hubPath\">连接四类主体，共同完成业务</div></div>\n      <button class=\"role-node rn1 active\" data-role=\"人才\"><div class=\"avatar-illustration\"><span></span></div><strong>人才端</strong><small>学习 · 实训 · 揭榜 · 项目 · 成长</small></button>\n      <button class=\"role-node rn2\" data-role=\"企业\"><div class=\"avatar-illustration corp\"><span></span></div><strong>企业端</strong><small>需求 · 人才 · 项目 · 验收 · 成果</small></button>\n      <button class=\"role-node rn3\" data-role=\"导师\"><div class=\"avatar-illustration mentor\"><span></span></div><strong>导师专家端</strong><small>授课 · 辅导 · 评审 · 评价</small></button>\n      <button class=\"role-node rn4\" data-role=\"运营\"><div class=\"avatar-illustration opsavatar\"><span></span></div><strong>社区运营端</strong><small>招募 · 培训 · 撮合 · 项目 · 孵化</small></button>\n    </div>\n    <aside class=\"role-detail\"><div class=\"rd-kicker\">CURRENT ROLE</div><h2 id=\"roleTitle\">人才端</h2><div id=\"roleFlow\" class=\"role-flow\"><span>加入社区</span><i>→</i><span>学习实训</span><i>→</i><span>揭榜项目</span><i>→</i><span>完成交付</span><i>→</i><span>能力成长</span></div><p id=\"roleDesc\">平台让人才从“报名成员”逐步成长为具备真实项目交付能力的 OPC。</p><div class=\"role-visual-mini\"><div class=\"mini-person\"></div><div class=\"mini-path\"><span></span><span></span><span></span><span></span></div></div></aside>\n  </div>\n  <div class=\"role-conclusion\">平台的核心不是“提供功能”，而是连接四类主体共同完成业务。</div>\n</section>");
